=== getConfig.mjs (what config:contentful fetches) ===
#!/usr/bin/env node
/**
 * Populate .env with Contentful API tokens fetched live from the space.
 *
 * Rules:
 *   - Missing var  → added at the end of the Contentful block
 *   - Empty var    → filled with the live value
 *   - Wrong var    → updated with the live value
 *   - CONTENTFUL_MANAGEMENT_TOKEN → never touched (per-user personal token)
 *
 * Write access (add/update) is gated to @ZimmermannAU/tier-1-approvers.
 * Non-approvers get a read-only view of what the values should be.
 *
 * Usage:
 *   npm run config:contentful               # update .env if authorised
 *   npm run config:contentful -- --dry-run  # print changes without writing
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { execSync } from 'child_process';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { checkEnv, createClient, log } from './_shared.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '../../../');
const ENV_FILE = resolve(REPO_ROOT, '.env');
const DRY_RUN = process.argv.includes('--dry-run');

const ENVIRONMENT_IDS = ['master', 'dev', 'test', 'sit', 'staging', 'uat'];
const SKIP_VARS = new Set(['CONTENTFUL_MANAGEMENT_TOKEN']);

// Vars managed by this script, keyed by their .env name
const MANAGED_VARS = [
  'CONTENTFUL_SPACE_ID',
  'CONTENTFUL_ENVIRONMENT_ID',
  'CONTENTFUL_DELIVERY_TOKEN',
  'CONTENTFUL_PREVIEW_TOKEN',
];

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);

// ── Tier 1 gate ──────────────────────────────────────────────────────────────

async function isTier1Approver() {
  try {
    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
    const membersRaw = execSync(
      "gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'",
      { encoding: 'utf8' },
    ).trim();
    const members = membersRaw.split('\n').filter(Boolean);
    return { approved: members.includes(login), login };
  } catch {
    return { approved: false, login: 'unknown' };
  }
}

// ── .env parsing ─────────────────────────────────────────────────────────────

